/** Inline label and details action above one editable node. */
export function DiagramInlineNodeControls({ autoWrap, contentInset, node, onOpenDetails, session }: {
    autoWrap: boolean
    contentInset: number
    node: PositionedDiagramNode
    onOpenDetails: () => void
    session: DiagramEditSessionService
}) {
    const [draftState, setDraftState] = useState({ base: node.label, value: node.label })
    const draft = draftState.base === node.label ? draftState.value : node.label
    const [error, setError] = useState<string | null>(null)
    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
        setDraftState({ base: node.label, value: event.target.value })
        setError(null)
    }
    const commit = () => {
        if (draft.trim() === node.label) return
        if (!draft.trim()) {
            setError('Label is required.')

            return
        }
        if (!session.objects.setNodeField(node.id, 'label', draft.trim())) setError('Label could not be saved.')
    }
    const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Escape') {
            event.stopPropagation()
            setDraftState({ base: node.label, value: node.label })
            setError(null)

            return
        }
        if (event.key !== 'Enter') return
        event.preventDefault()
        commit()
    }
    const stopPointer = (event: PointerEvent<HTMLElement>) => {
        if (session.read.getActiveToolSnapshot().startsWith('edge:')) return
        event.stopPropagation()
    }
    const stopClick = (event: MouseEvent<HTMLElement>) => event.stopPropagation()
    const handleDoubleClick = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        onOpenDetails()
    }

    return (
        <Box
            className="diagram-node-inline-controls"
            data-diagram-connection-target={node.id}
            onClick={stopClick}
            onDoubleClick={handleDoubleClick}
            onPointerDown={stopPointer}
            sx={{
                height: node.height, left: node.x, pointerEvents: 'none', position: 'absolute', top: node.y,
                width: node.width, zIndex: 3,
                '& .diagram-node-details-action': { opacity: 0 },
                '&:hover .diagram-node-details-action, &:focus-within .diagram-node-details-action': { opacity: 1 },
                '@media (hover: none)': { '& .diagram-node-details-action': { opacity: 1 } },
            }}
        >
            <TextField
                error={!!error}
                helperText={error}
                multiline={autoWrap}
                onBlur={commit}
                onChange={handleChange}
                onKeyDown={handleKeyDown}
                size="small"
                slotProps={{ htmlInput: { 'aria-label': `Edit ${node.label} label` } }}
                sx={{
                    left: contentInset, pointerEvents: 'auto', position: 'absolute', right: contentInset,
                    top: '50%', transform: 'translateY(-50%)',
                    '& .MuiInputBase-root': { bgcolor: 'transparent' },
                    '& .MuiInputBase-input': { overflowWrap: autoWrap ? 'anywhere' : 'normal', textAlign: 'center', whiteSpace: autoWrap ? 'pre-wrap' : 'nowrap' },
                }}
                value={draft}
                variant="standard"
            />
            <Tooltip title={`Details for ${node.label}`}>
                <IconButton
                    aria-label={`Details for ${node.label}`}
                    className="diagram-node-details-action"
                    onClick={onOpenDetails}
                    size="small"
                    sx={{ pointerEvents: 'auto', position: 'absolute', right: 2, top: 2 }}
                >
                    <MoreHorizOutlined fontSize="small" />
                </IconButton>
            </Tooltip>
        </Box>
    )
}

const TARGET_CHANGED_EVENT = 'targetChanged'

export type DiagramDetailsObjectKind = 'edge' | 'group' | 'node'

interface DiagramObjectTarget {
    objectId: string
    objectKind: DiagramDetailsObjectKind
}

/** Diagram-wide editors addressed by kind alone, because the diagram owns exactly one of each. */
interface DiagramSingletonTarget {
    objectKind: 'legend' | 'meta'
}

export type DiagramObjectDetailsTarget = DiagramSingletonTarget | DiagramObjectTarget

function isSingletonTarget(target: DiagramObjectDetailsTarget): target is DiagramSingletonTarget {
    return target.objectKind === 'legend' || target.objectKind === 'meta'
}

function sameTarget(left: DiagramObjectDetailsTarget | null, right: DiagramObjectDetailsTarget) {
    if (!left || left.objectKind !== right.objectKind) return false
    if (isSingletonTarget(left) || isSingletonTarget(right)) return true

    return left.objectId === right.objectId
}

/** Owns which New-diagram object has its details dialog open. */
export class DiagramObjectDetailsService extends EventTarget {
    private target: DiagramObjectDetailsTarget | null = null

    getTargetSnapshot = () => this.target

    subscribeTarget = (listener: () => void) => {
        this.addEventListener(TARGET_CHANGED_EVENT, listener)

        return () => this.removeEventListener(TARGET_CHANGED_EVENT, listener)
    }

    open(target: DiagramObjectDetailsTarget) {
        if (!isSingletonTarget(target) && target.objectId.trim().length === 0) {
            throw new Error('Diagram details object ID is required')
        }
        if (sameTarget(this.target, target)) return false

        this.target = { ...target }
        this.dispatchEvent(new Event(TARGET_CHANGED_EVENT))

        return true
    }

    close() {
        if (!this.target) return false

        this.target = null
        this.dispatchEvent(new Event(TARGET_CHANGED_EVENT))

        return true
    }
}

